def minEatingSpeed(piles: List[int], h: int) -> int:
    import math
    speed = 1
    while True:
        hours_needed = 0
        for p in piles:
            hours_needed += math.ceil(p / speed)
        if hours_needed <= h:
            return speed
        speed += 1

